def _no_log_strings(no_log_strings):
    # Longer matches go first so overlapping strings produce a stable result.
    strings = set(to_native(s, errors='surrogate_or_strict') for s in no_log_strings)
    strings.discard('')
    return sorted(strings, key=lambda s: (-len(s), s))


def _redact_string(value, no_log_strings, exact_key=False):
    if not no_log_strings or not isinstance(value, (text_type, binary_type)):
        return value

    native_value = to_native(value, errors='surrogate_or_strict')
    if exact_key and native_value in no_log_strings:
        return 'VALUE_SPECIFIED_IN_NO_LOG_PARAMETER'

    pattern = '|'.join(re.escape(secret) for secret in no_log_strings)
    redacted = re.sub(pattern, lambda match: '********', native_value)
    if redacted == native_value:
        return value
    if isinstance(value, binary_type) and isinstance(redacted, text_type):
        return to_bytes(redacted, errors='surrogate_or_strict')
    if isinstance(value, text_type) and isinstance(redacted, binary_type):
        return to_text(redacted, errors='surrogate_or_strict')
    return redacted


def _sanitize_container(value, no_log_strings, sanitize_mapping_keys=False, ignore_keys=frozenset()):
    """Copy containers from the leaves up without recursive Python calls."""
    def is_container(item):
        return not isinstance(item, (text_type, binary_type)) and isinstance(item, (Mapping, Sequence, Set))

    if not is_container(value):
        return value if sanitize_mapping_keys else _redact_string(value, no_log_strings)

    results = {}
    pending = [(value, False)]
    while pending:
        old, ready = pending.pop()
        if not ready:
            pending.append((old, True))
            children = old.values() if isinstance(old, Mapping) else old
            for child in children:
                if is_container(child):
                    pending.append((child, False))
        elif isinstance(old, Mapping):
            if isinstance(old, MutableMapping):
                new = copy.copy(old)
                new.clear()
            else:
                new = {}
            for key, child in old.items():
                if sanitize_mapping_keys and key not in ignore_keys:
                    native_key = None
                    if isinstance(key, (text_type, binary_type)):
                        native_key = to_native(key, errors='surrogate_or_strict')
                    if native_key is not None and not native_key.startswith('_ansible'):
                        key = _redact_string(key, no_log_strings, exact_key=True)
